selector_to_html = {"a[href=\"syllabus.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Syllabus<a class=\"headerlink\" href=\"#syllabus\" title=\"Link to this heading\">#</a></h1><h2>Course overview<a class=\"headerlink\" href=\"#course-overview\" title=\"Link to this heading\">#</a></h2><p>This course develops the foundations of Lebesgue measure and integration and the <span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"L^p\" data-math-display=\"inline\" data-math-speech=\"L to the p-th power\" role=\"math\" aria-label=\"Math: L to the p-th power. Original TeX: L^p\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: 0;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"2.533ex\" height=\"1.548ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -684 1119.7 684\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><defs><path id=\"MJX-1-NCM-I-1D43F\" d=\"M520 667C520 678 513 683 500 683L354 680L223 683C208 684 200 676 200 659C200 652 203 647 209 646C218 645 226 644 231 644C262 643 279 641 284 640C289 639 292 636 292 631C292 629 291 623 288 613L156 82C150 60 140 47 125 42C119 40 101 39 70 39C49 39 39 31 39 15C39 5 49 0 70 0L527 0C552 0 554 0 561 19L639 233C642 240 643 245 643 248C643 258 638 263 627 263C617 263 612 254 607 240C588 191 570 154 555 131C518 75 455 39 363 39L270 39C259 39 252 39 249 40C242 40 239 42 239 45C239 47 241 54 244 67L377 601C383 624 396 637 415 642C421 643 442 644 478 644C506 644 520 644 520 667Z\"></path><path id=\"MJX-1-NCM-I-1D45D\" d=\"M355 442C311 442 269 419 228 373C217 419 186 442 137 442C96 442 66 409 45 344C35 311 30 292 30 286C30 277 35 272 46 272C51 272 54 273 57 275C62 284 65 291 66 298C84 374 107 412 134 412C152 412 161 398 161 371C161 356 159 339 154 321L44-118C35-151 34-155-5-155C-23-155-32-163-32-178C-32-189-26-194-15-194C0-194 52-191 67-191C86-191 146-194 165-194C180-194 187-186 187-170C187-160 178-155 159-155C141-155 114-156 114-144C114-131 155 26 159 43C179 6 209-13 249-13C314-13 371 20 421 87C467 148 490 213 490 280C490 367 438 442 355 442M352 412C391 412 411 382 411 323C411 296 405 260 394 215C371 128 342 71 307 42C286 25 267 16 248 16C219 16 199 29 188 56C179 77 174 92 174 100L225 309C230 331 248 354 276 377C304 400 329 412 352 412Z\"></path></defs><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\"><g data-mml-node=\"msup\"><g data-mml-node=\"mi\"><use data-c=\"1D43F\" xlink:href=\"#MJX-1-NCM-I-1D43F\"></use></g><g data-mml-node=\"mi\" transform=\"translate(714,363) scale(0.707)\"><use data-c=\"1D45D\" xlink:href=\"#MJX-1-NCM-I-1D45D\"></use></g></g></g></g></svg></mjx-container></span> spaces that underpin modern analysis, partial differential equations, probability, and harmonic analysis.\nWe begin by identifying limitations of Riemann integration, then we construct measures - ways of describing how large a set is. We then develop measurable functions and use the notion of measure to construct the  Lebesgue integral, describing how large functions are.\nNext, we prove the major limit theorems for the Lebesgue integral, then and study normed spaces of integrable functions.\nThe final part of the course treats product measures and the Tonelli-Fubini theorems.</p>","a[href=\"#start-here\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Start here<a class=\"headerlink\" href=\"#start-here\" title=\"Link to this heading\">#</a></h2><p>Please check the <a class=\"reference internal\" href=\"calendar.html\"><span class=\"std std-doc\">course calendar</span></a> for holidays, University deadlines, and topic updates.</p>","a[href=\"assignments/index.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Assignments<a class=\"headerlink\" href=\"#assignments\" title=\"Link to this heading\">#</a></h1><h2>Weekly written homework<a class=\"headerlink\" href=\"#weekly-written-homework\" title=\"Link to this heading\">#</a></h2><p>I will post written homework here approximately weekly. Submit through Gradescope using the links in <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529398_1/outline/\">Blackboard &gt; Assignments &gt; Homework</a>.</p><p>You are encouraged to work in groups of up to three. Make one submission per group and list every group member clearly.</p>","a[href=\"calendar.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Calendar<a class=\"headerlink\" href=\"#calendar\" title=\"Link to this heading\">#</a></h1><p>I will put all deadlines on your <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529398_1/calendar/\">Blackboard Calendar</a>. Please check it regularly!</p>","a[href=\"resources.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">#</a></h1><p>For every topic we cover, I will provide either lecture notes or a precise reading reference. The books below offer complementary treatments; you do not need to purchase them.</p>","a[href=\"lecture-notes/index.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Lecture Notes<a class=\"headerlink\" href=\"#lecture-notes\" title=\"Link to this heading\">#</a></h1><p>Lecture notes will be added here as the semester progresses. Until a note is published, use the reading listed in the <a class=\"reference internal\" href=\"calendar.html#daily-lecture-log\"><span class=\"std std-ref\">daily lecture log</span></a>.</p>","a[href=\"#real-variables-i-math55003-01-fall-2026\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">REAL VARIABLES I MATH55003-01 – Fall 2026<a class=\"headerlink\" href=\"#real-variables-i-math55003-01-fall-2026\" title=\"Link to this heading\">#</a></h1><p><strong>Semester:</strong> Fall 2026</p><p><strong>Instructor:</strong> Gennady Uraltsev</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "no-hover-preview"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
